#include "wled.h"
#include "saulux.h"

#if defined(SAULUX) && !defined(WLED_DISABLE_MQTT)
#include <atomic>

// AI: below section was generated by an AI
namespace {
constexpr uint8_t INPUT_COUNT = SAULUX_MODEL == 2 ? 5 : 2;
constexpr uint32_t INPUT_POLL_MS = 10;
constexpr uint32_t INPUT_DEBOUNCE_MS = 50;
constexpr uint32_t PUBLISH_RETRY_MS = 250;
struct InputState {
  int8_t pin = -1;
  uint8_t type = BTN_TYPE_NONE;
  bool initialized = false;
  bool raw = false;
  bool stable = false;
  bool ready = false;
  bool announced = false;
  bool retryPending = false;
  uint32_t changedAt = 0;
  uint32_t attemptedAt = 0;
};
InputState inputStates[INPUT_COUNT];
std::atomic<bool> refreshInputs{true};
char inputTopic[MQTT_MAX_TOPIC_LEN + 1] = {};
uint32_t lastInputPoll = 0;

// Read logical pressed/released state only for button types supported by isButtonPressed().
bool isDigitalInput(uint8_t type) {
  switch (type) {
    case BTN_TYPE_PUSH:
    case BTN_TYPE_PUSH_ACT_HIGH:
    case BTN_TYPE_SWITCH:
    case BTN_TYPE_PIR_SENSOR:
    case BTN_TYPE_TOUCH:
    case BTN_TYPE_TOUCH_SWITCH:
      return true;
    default: return false;
  }
}
}

// MQTT callbacks can run on the TCP task; GPIO sampling and state changes stay in the main loop.
void onSauluxMqttConnect() {
  refreshInputs.store(true, std::memory_order_relaxed);
}

// Publish debounced input states once per change and refresh the snapshot after reconnecting.
void handleSauluxMqttInputs() {
  const uint32_t now = millis();
  if (now - lastInputPoll < INPUT_POLL_MS) return;
  lastInputPoll = now;
  if (!mqttEnabled || mqttDeviceTopic[0] == '\0') {
    for (auto& input : inputStates) input = InputState{};
    refreshInputs.store(true, std::memory_order_relaxed);
    return;
  }
  const bool refresh = refreshInputs.exchange(false, std::memory_order_relaxed);
  if (refresh || strncmp(inputTopic, mqttDeviceTopic, sizeof(inputTopic)) != 0) {
    snprintf_P(inputTopic, sizeof(inputTopic), PSTR("%.*s"), MQTT_MAX_TOPIC_LEN, mqttDeviceTopic);
    for (auto& input : inputStates) {
      input.announced = false;
      input.retryPending = false;
    }
  }
  for (uint8_t i = 0; i < INPUT_COUNT; i++) {
    auto& input = inputStates[i];
    const bool configured = buttonPublishMqtt && i < buttons.size();
    const int8_t pin = configured ? buttons[i].pin : -1;
    const uint8_t type = configured ? buttons[i].type : BTN_TYPE_NONE;
    if (pin != input.pin || type != input.type) {
      input = InputState{};
      input.pin = pin;
      input.type = type;
    }
    const bool valid = pin >= 0 && isDigitalInput(type);
    if (valid) {
      const bool pressed = isButtonPressed(i);
      if (!input.initialized || pressed != input.raw) {
        input.raw = pressed;
        input.changedAt = now;
        input.initialized = true;
      }
      if ((!input.ready || input.stable != input.raw) && now - input.changedAt >= INPUT_DEBOUNCE_MS) {
        input.stable = input.raw;
        input.ready = true;
        input.announced = false;
        input.retryPending = false;
      }
      if (!input.ready) continue;
    }
    if (input.announced || !WLED_MQTT_CONNECTED) continue;
    if (input.retryPending && now - input.attemptedAt < PUBLISH_RETRY_MS) continue;
    char topic[MQTT_MAX_TOPIC_LEN + sizeof("/input/5/state")];
    snprintf_P(topic, sizeof(topic), PSTR("%s/input/%u/state"), inputTopic, unsigned(i + 1));
    // Empty retained payload removes stale state when a port or button publishing is disabled.
    const char* payload = valid ? (input.stable ? "1" : "0") : "";
    input.announced = mqtt->publish(topic, 1, true, payload) != 0;
    input.retryPending = !input.announced;
    input.attemptedAt = now;
  }
}
// AI: end
#endif
